pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 blockTimestamp) public {
        vm.assume(blockTimestamp > 0);
        vm.assume(blockTimestamp > c.pastBlockTime());
        vm.assume(blockNumber % 15 == 0);
        vm.roll(blockNumber);
        vm.warp(blockTimestamp);
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok ? address(c).balance == 0 : true);
    }
}
